// ---- canvas transforms ----
export function rotate(c, rot) { // quarter turns about y, same mapping as the lab's World.place
  rot &= 3; if (!rot) return c; const { sx, sy, sz } = c; const o = new Canvas(rot & 1 ? sz : sx, sy, rot & 1 ? sx : sz);
  for (let y = 0; y < sy; y++) for (let z = 0; z < sz; z++) for (let x = 0; x < sx; x++) { const m = c.v[x + sx * (z + sz * y)]; if (!m) continue; const mx = rot === 1 ? sz - 1 - z : rot === 2 ? sx - 1 - x : z; const mz = rot === 1 ? x : rot === 2 ? sz - 1 - z : sx - 1 - x; o.v[mx + o.sx * (mz + o.sz * y)] = m; }
  return o;
}
export function half(c) { // 0.2 m tier: a cell is solid when at least two of its eight voxels are; it takes the commonest material
  const sx = Math.ceil(c.sx / 2); const sy = Math.ceil(c.sy / 2); const sz = Math.ceil(c.sz / 2); const o = new Canvas(sx, sy, sz); const cnt = new Uint8Array(256);
  for (let y = 0; y < sy; y++) for (let z = 0; z < sz; z++) for (let x = 0; x < sx; x++) {
    let n = 0; let best = 0; let bn = 0; const seen = [];
    for (let q = 0; q < 8; q++) { const m = c.get(x * 2 + (q & 1), y * 2 + ((q >> 1) & 1), z * 2 + (q >> 2)); if (!m) continue; n++; if (!cnt[m]) seen.push(m); if (++cnt[m] > bn) { bn = cnt[m]; best = m; } }
    for (const m of seen) cnt[m] = 0; if (n >= 2) o.v[x + sx * (z + sz * y)] = best;
  }
  return o;
}

// ---- the plan: every lot of the square. x, z = the lot's corner nearest (-x, -z) in metres; rot = quarter turns (0 faces -z,
// 1 faces +x, 2 faces +z, 3 faces -x) ----
