  const put = (name, kind, sd, x, z, rot, o = {}) => { const c = rotate(make(kind, sd), rot); const lot = { name, kind, seed: sd, canvas: c, x: snap(x), z: snap(z), rot, w: c.sx / 10, d: c.sz / 10, big: !!o.big }; lots.push(lot); return lot; };
