  row('shophouses', -33.4, -5.2, 2, [s(1) * 4 + 0, s(2) * 4 + 1, s(3) * 4 + 2, s(4) * 4 + 3], ['sign_taphoa', 'sign_caphe', 'sign_pho', null]);
  put('apartment', 'apartment', s(5) * 4 + 1, -15.8, -33.6, 1, { big: true });
